form [style*="grid-template-columns: repeat(2, minmax(0, 1fr))"]{grid-template-columns:minmax(0,1fr)!important}
#contact h2{font-size:36px!important}
#contact [style*="gap: 48px"]{gap:24px!important}
#xsell{min-height:0!important;padding:56px 16px 40px!important}
#xsGrid{display:flex!important;flex-direction:column!important;min-height:0!important}
