}

@media (max-width: 767px){
header>a>img{height:32px!important}
#hero .crumb{font-size:12px}
#hero h1{font-size:34px!important;line-height:1.02!important}
#hero .lead{font-size:15px!important}
#hero [style*="font-size: clamp(72px, 9vw, 150px)"]{font-size:68px!important}
#hero [style*="font-size: clamp(17px, 1.4vw, 22px)"]{font-size:15px!important}
#hero [style*="font-size: 17px; color: rgba(244,243,239,.72)"]{font-size:15px!important}
#hero>div>div>video{object-position:62% 50%!important}
